const $=id=>document.getElementById(id);
let accountUser = null, accountBusy = false;
let accountEnabled = false, welcomeAuthMode = 'login';
let guestMode = false, authReturnPage = null;
try { guestMode = sessionStorage.getItem('mrElecGuest') === '1'; } catch (e) {}
function setGuestMode(value) {
  guestMode = value;
  try { value ? sessionStorage.setItem('mrElecGuest', '1') : sessionStorage.removeItem('mrElecGuest'); } catch (e) {}
}
function requireAccount() {
  if (accountUser) return true;
  openAuth('login');
  $('welcomeAuthMessage').textContent = 'เข้าสู่ระบบเพื่ออัปโหลดบิล ใช้แชท และบันทึกบ้านที่แต่งไว้ในบัญชี';
  return false;
}
function updateGuestAccess() {
  document.body.classList.toggle('guest-mode', guestMode && !accountUser);
  if ($('guestBanner')) $('guestBanner').hidden = !guestMode || !!accountUser;
  if ($('accountName')) $('accountName').textContent = accountUser?.name || accountUser?.email || (guestMode ? 'Guest · ทดลองใช้งาน' : '');
  if ($('welcomeGuestTools')) $('welcomeGuestTools').hidden = !guestMode || !!accountUser;
  if ($('logoutButton')) {
    $('logoutButton').title = accountUser ? 'ออกจากระบบ' : 'เข้าสู่ระบบเพื่อเก็บบ้านนี้';
    $('logoutButton').setAttribute('aria-label', $('logoutButton').title);
  }
  if ($('f')) $('f').disabled = !accountUser;
  if ($('q')) $('q').disabled = false;
  if ($('homeSocialContent')) $('homeSocialContent').hidden = !accountUser;
  if ($('homeSocialLogin')) $('homeSocialLogin').hidden = !!accountUser;
  if ($('mini')) $('mini').hidden = !accountUser;
  if ($('billDemoButton')) $('billDemoButton').hidden = !!accountUser || !guestMode;
  if ($('clearBillsButton')) $('clearBillsButton').disabled = bills.length === 0;
  document.querySelectorAll('#rows input, #rows .bill-delete-btn').forEach(el => el.disabled = !accountUser);
}
function enterGuest(page = null) {
  if (accountBusy) return;
  if (accountUser) return enterApp(accountUser, page ?? 0);
  setGuestMode(true);
  window.loadGuestHome?.();
  bills = []; D = {}; turns = []; $('log').replaceChildren(); $('f').value = '';
  window.loadGuestDraft?.();
  let guestBillsCleared=false;
  try{guestBillsCleared=sessionStorage.getItem('mrElecGuestBillsCleared')==='1'}catch(e){}
  if(guestBillsCleared)rows();else demo();
  showWelcome();
  if (page !== null) enterApp(null, page);
  updateGuestAccess();
}
window.enterGuest = enterGuest;


function updateWelcomeAccount() {
  const tools = $('welcomeAccountTools');
  const name = $('welcomeAccountName');
  if (!tools || !name) return;

  if (accountUser) {
    tools.hidden = false;
    name.textContent = accountUser.name || accountUser.email || '';
  } else {
    tools.hidden = true;
    name.textContent = '';
  }
}

function renderWelcomeHousePreview(){
  const source=$('room');
  const target=$('welcomeRoomPreview');
  if(!source||!target)return;

  // Mirror the editable house without copying its interactions.
  let svg=source.innerHTML||'';
  svg=svg
    .replaceAll('id="stk"','id="preview_stk"')
    .replaceAll('url(#stk)','url(#preview_stk)')
    .replaceAll('id="sh"','id="preview_sh"')
    .replaceAll('url(#sh)','url(#preview_sh)')
    .replaceAll('style="cursor:grab"','');

  svg=svg.replace(/<foreignObject[\s\S]*?<\/foreignObject>/g,'');
  const vb=source.getAttribute('viewBox');if(vb)target.setAttribute('viewBox',vb);
  target.innerHTML=svg;

  const total=EL.reduce((sum,a)=>sum+kw(a),0);
  const price=+$('price').value||0;
  const currency=cur();

  if($('welcomeHomeKwh')) $('welcomeHomeKwh').textContent=total.toFixed(0);
  if($('welcomeHomeCost')) $('welcomeHomeCost').textContent=(total*price).toFixed(0);
  if($('welcomeHomeCurrency')) $('welcomeHomeCurrency').textContent=currency;
}

function showWelcome(user = null) {
  if (user) accountUser = user;
  $('appShell').hidden = true;
  $('welcomePage').hidden = false;
  updateWelcomeAccount();
  updateGuestAccess();
  closeAuth(true);
  window.scrollTo(0, 0);

  // The real editor lives in p0. Render it off-screen, then mirror
  // only the visual room onto the non-editable Welcome preview.
  setTimeout(() => {
    try {
      if (typeof pl === 'function') pl();
      else if (typeof room === 'function') room();
      renderWelcomeHousePreview();
    } catch (e) {
      console.warn('Welcome house preview:', e);
    }
  }, 0);
}

function enterApp(user, page = 2) {
  accountUser = user || accountUser;
  if (!accountUser && !guestMode) {
    openAuth('login');
    return;
  }

  $('welcomePage').hidden = true;
  $('authModal').hidden = true;
  document.body.classList.remove('modal-open');
  $('appShell').hidden = false;
  updateGuestAccess();
  go(page);
}


function openEditableHome(){
  if(!accountUser && !guestMode){
    openAuth('login');
    return;
  }

  $('welcomePage').hidden=true;
  $('authModal').hidden=true;
  document.body.classList.remove('modal-open');
  $('appShell').hidden=false;
  updateGuestAccess();

  go(0);
}

window.openEditableHome=openEditableHome;

function openWelcomeFeature(page = 2) {
  if (!accountUser && !guestMode) {
    openAuth('login');
    return;
  }
  enterApp(accountUser, page);
}

window.openWelcomeFeature = openWelcomeFeature;

function initAccount(config) {
  accountEnabled = !!config?.enabled;
  accountUser = config?.user || null;

  // ถ้ามี session อยู่แล้ว ให้เข้าหน้า Welcome ก่อนเหมือนกัน
  // แล้วผู้ใช้ค่อยกด "เริ่มใช้งาน" เพื่อเข้า App
  if (accountUser) {
    if (guestMode) { window.loadGuestHome?.(); window.adoptGuestHome?.(accountUser); window.loadGuestDraft?.(); window.adoptGuestDraft?.(accountUser); }
    setGuestMode(false);
    showWelcome(accountUser);
    return;
  }

  if (guestMode) { enterGuest(); return; }

  // ยังไม่ได้ล็อกอิน:
  // แสดง Welcome ไว้ด้านหลัง และบังคับเปิด Login modal ก่อน
  $('appShell').hidden = true;
  $('welcomePage').hidden = false;

  const msg =
    config?.message ||
    (!accountEnabled
      ? 'ระบบบัญชียังไม่พร้อมใช้งาน กรุณาตรวจสอบการตั้งค่า Firebase'
      : '');

  if ($('welcomeAuthMessage')) {
    $('welcomeAuthMessage').textContent = msg;
  }

  openAuth('login');
}

function selectWelcomeAuthMode(mode) {
  if (accountBusy) return;
  welcomeAuthMode = mode === 'register' ? 'register' : 'login';
  const registering = welcomeAuthMode === 'register';

  $('modalAuthTitle').textContent = registering ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ';
  $('modalAuthIntro').textContent = registering
    ? 'สร้างบัญชี MR ELEC เพื่อบันทึกและกลับมาดูข้อมูลของคุณได้'
    : 'เข้าสู่ระบบเพื่อดูข้อมูลและจัดการค่าไฟของคุณ';

  $('welcomeAuthSubmit').textContent = registering ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ';
  $('welcomeNameField').hidden = $('welcomeConfirmField').hidden = !registering;
  $('welcomeAuthName').required = registering;
  $('welcomeAuthConfirm').required = registering;

  $('welcomeAuthPassword').autocomplete = registering ? 'new-password' : 'current-password';
  $('welcomeAuthPassword').minLength = registering ? 8 : 1;
  $('welcomeAuthPassword').maxLength = registering ? 128 : 4096;
  $('welcomeAuthPassword').placeholder = registering ? 'อย่างน้อย 8 ตัวอักษร' : 'รหัสผ่านของคุณ';

  $('modalLoginTab').className = registering ? 'g' : '';
  $('modalRegisterTab').className = registering ? '' : 'g';
  $('welcomeAuthPassword').value = '';
  $('welcomeAuthConfirm').value = '';
  if (accountEnabled) $('welcomeAuthMessage').textContent = '';
}

function openAuth(mode = 'login') {
  // หลังล็อกอินแล้ว ปุ่ม "เริ่มใช้งาน" และการ์ดต่าง ๆ
  // จะพาเข้า App แทนการเปิด Login ซ้ำ
  if (accountUser) {
    enterApp(accountUser, 2);
    return;
  }

  if (guestMode && !$('appShell').hidden) authReturnPage = [0,1,2,3].find(i => !$('p'+i)?.hidden) ?? null;
  selectWelcomeAuthMode(mode);
  $('authModal').hidden = false;
  document.body.classList.add('modal-open');
  setTimeout(() => $('welcomeAuthEmail')?.focus(), 0);
}

function closeAuth(force = false) {
  if (!$('authModal')) return;
  if (!force && accountBusy) return;
  // The close button follows the same Guest flow as the trial button.
  if (!force && !accountUser && !guestMode) {
    const page = authReturnPage;
    authReturnPage = null;
    enterGuest(page);
    return;
  }

  $('authModal').hidden = true;
  document.body.classList.remove('modal-open');
}

window.openAuth = openAuth;
window.closeAuth = closeAuth;
window.selectWelcomeAuthMode = selectWelcomeAuthMode;

$('welcomeAuthForm').onsubmit = async event => {
  event.preventDefault();
  if (accountBusy || !accountEnabled || !$('welcomeAuthForm').reportValidity()) return;

  const registering = welcomeAuthMode === 'register';
  if (registering && $('welcomeAuthPassword').value !== $('welcomeAuthConfirm').value) {
    $('welcomeAuthMessage').textContent = 'รหัสผ่านทั้งสองช่องไม่ตรงกัน';
    return;
  }

  const payload = {
    action: registering ? 'auth.register' : 'auth.login',
    email: $('welcomeAuthEmail').value.trim(),
    password: $('welcomeAuthPassword').value,
    ...(registering ? { name: $('welcomeAuthName').value.trim() } : {})
  };

  accountBusy = true;
  $('welcomeAuthSubmit').disabled = true;
  $('welcomeAuthMessage').textContent = registering ? 'กำลังสมัครสมาชิก...' : 'กำลังเข้าสู่ระบบ...';

  try {
    const result = await window.StreamlitBridge.request(payload);
    if (result?.user) {
      $('welcomeAuthMessage').textContent = 'สำเร็จ';
      $('welcomeAuthPassword').value = $('welcomeAuthConfirm').value = '';

      // ล็อกอินสำเร็จแล้ว: กลับมาแสดงหน้า Welcome ตามภาพ
      // ยังไม่เข้า App จนกว่าจะกด "เริ่มใช้งาน"
      window.adoptGuestHome?.(result.user);
      window.adoptGuestDraft?.(result.user);
      const returnPage = authReturnPage;
      authReturnPage = null;
      setGuestMode(false);
      showWelcome(result.user);
      if (returnPage !== null) enterApp(result.user, returnPage);
      updateGuestAccess();
    } else {
      $('welcomeAuthMessage').textContent = result?.message || 'ไม่สามารถเข้าสู่ระบบได้';
    }
  } catch (error) {
    $('welcomeAuthMessage').textContent = error.message || 'เกิดข้อผิดพลาด';
  } finally {
    payload.password = '';
    accountBusy = false;
    $('welcomeAuthSubmit').disabled = !accountEnabled;
  }
};

document.addEventListener('keydown', event => {
  if (event.key === 'Escape' && !$('authModal').hidden) closeAuth();
});

async function performLogout(button = null) {
  if (accountBusy) return;
  if (!accountUser) { openAuth('login'); return; }
  accountBusy = true;
  window.saveHomeNow?.();

  const buttons = [$('logoutButton'), $('welcomeLogoutButton')].filter(Boolean);
  buttons.forEach(btn => btn.disabled = true);
  ctl?.abort();

  try {
    await window.StreamlitBridge.request({ action: 'auth.logout' });
    accountUser = null;
    setGuestMode(false);
    E=null; D={};
    window.clearHomeOwner?.();
    for(const id of ['sv','iv','tips','cv','pv'])if($(id))$(id).replaceChildren();
    turns = []; $('log').replaceChildren(); $('f').value = ''; $('q').value = '';
    window.clearChatDraftOwner?.();
    updateGuestAccess();
    updateWelcomeAccount();
    $('appShell').hidden = true;
    $('welcomePage').hidden = false;
    openAuth('login');
  } catch (error) {
    const msg = error?.message || 'ออกจากระบบไม่สำเร็จ';
    if (button) {
      const label = button.querySelector('span');
      if (label) label.textContent = msg;
      else button.textContent = msg;
    }
  } finally {
    accountBusy = false;
    buttons.forEach(btn => btn.disabled = false);
  }
}

if ($('logoutButton')) {
  $('logoutButton').onclick = () => performLogout($('logoutButton'));
}

if ($('welcomeLogoutButton')) {
  $('welcomeLogoutButton').onclick = () => performLogout($('welcomeLogoutButton'));
}
