/* ===== hair meshes helpers (data lives in hair_data.js) ===== */
function hairData(id){if(!HAIRD.s[id])id='long';if(HAIRC[id])return HAIRC[id];const d=HAIRD.s[id],bin=atob(d.b64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
const p=new Int16Array(u.buffer,0,d.nv*3),P=new Float32Array(p.length);for(let i=0;i<p.length;i++)P[i]=p[i]/1000;
return HAIRC[id]={P,I:new Uint16Array(u.buffer.slice(d.nv*6,d.nv*6+d.nt*6))}}
/* 2D thumbnail of a hairstyle (front view, painter's algorithm on a canvas) -> {b: layer behind the face, f: layer in front of the face} */
function hairThumb(id,col){const key=id+col;if(HAIRT[key])return HAIRT[key];
try{const D=hairData(id),P=D.P,I=D.I,hc=parseInt(col.slice(1),16),R=hc>>16&255,G=hc>>8&255,B=hc&255,SC=1.5,W=200*SC,H=160*SC,tr=[];
for(let t=0;t<I.length;t+=3){const a=I[t]*3,b=I[t+1]*3,c=I[t+2]*3,z=(P[a+2]+P[b+2]+P[c+2])/3,ux=P[b]-P[a],uy=P[b+1]-P[a+1],uz=P[b+2]-P[a+2],vx=P[c]-P[a],vy=P[c+1]-P[a+1],vz=P[c+2]-P[a+2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,nl=Math.hypot(nx,ny,nz)||1;tr.push([a,b,c,z,Math.abs((nx*.3+ny*.5+nz*.8)/nl)])}
tr.sort((m,n)=>m[3]-n[3]);
const lay=f=>{const cv=document.createElement('canvas');cv.width=W;cv.height=H;const x=cv.getContext('2d');x.lineJoin='round';x.lineWidth=.7;
for(const q of tr){if((q[3]>.25)!=f)continue;const k=.5+.5*q[4],sh='rgb('+Math.min(255,R*k*1.05|0)+','+Math.min(255,G*k*1.05|0)+','+Math.min(255,B*k*1.05|0)+')';x.fillStyle=x.strokeStyle=sh;x.beginPath();
[q[0],q[1],q[2]].forEach((v,i)=>{const X=(100+P[v]*40)*SC,Y=(78+(2.55-P[v+1])*40)*SC;i?x.lineTo(X,Y):x.moveTo(X,Y)});x.closePath();x.fill();x.stroke()}
return '<image href="'+cv.toDataURL('image/png')+'" x="0" y="0" width="200" height="160"/>'};
return HAIRT[key]={b:lay(false),f:lay(true)}}catch(e){return HAIRT[key]={b:'',f:''}}}
