function lin(x,y){
  const n=x.length;
  if(!n)return{a:0,b:0,s:0};
  const mx=x.reduce((a,b)=>a+b,0)/n,my=y.reduce((a,b)=>a+b,0)/n;
  let sxy=0,sxx=0;
  x.forEach((v,i)=>{sxy+=(v-mx)*(y[i]-my);sxx+=(v-mx)**2});
  const b=sxx?sxy/sxx:0,a=my-b*mx;
  return{a,b,s:n>2?Math.sqrt(y.reduce((q,v,i)=>q+(v-a-b*x[i])**2,0)/(n-2)):0}
}

