let TM = 'light';
function mode(value) {
  TM = value === 'dark' ? 'dark' : 'light';
  document.documentElement.dataset.theme = TM;
  document.querySelectorAll('[data-m]').forEach(button => {
    const selected = button.dataset.m === TM;
    button.classList.toggle('on2', selected);
    button.setAttribute('aria-pressed', String(selected));
  });
  try { localStorage.setItem('thm', JSON.stringify({m: TM})); } catch (error) {}
}
