/* ===== Home <-> Welcome sync: the room edited in "บ้านฉัน" is mirrored on the first page,
   updates live, and is remembered per account (localStorage) ===== */
(function(){
  const DEF={a:[],L:[],F:[],C:{...RC0},HT:'dorm',NN:6,FL:0,WL:[],P:[],DEC:1,PT:0,GD:1};
  const GUEST={guest:true};
  let owner=null,timer=null,restoring=false,last='',dirty=false;
  const key=u=>'homeRoom1:'+(u?.guest?'guest':u?.id||'guest');
  const settingIds=['price','pb','pf','pw'];
  const defaults=Object.fromEntries(settingIds.map(id=>[id,$(id)?.value||'']));
  const snap=()=>({a:apps,L:EL,F:FUR,C:RC,HT,NN,FL,WL,P:[...POOL],W:WK.on?1:0,DEC,PT,GD,
    settings:Object.fromEntries(settingIds.map(id=>[id,$(id)?.value||''])),
    garden:G,avatar:AV,shop:{PTS,OWN,CLM}});
  function save(){
    clearTimeout(timer);
    if(!owner||restoring||RT)return;
    const d=snap(),encoded=JSON.stringify({...d,a:d.a.map(({open,...x})=>x),L:d.L.map(({open,...x})=>x),garden:{m:d.garden?.m||{}}});
    if(owner.guest&&encoded!==last)dirty=true;
    last=encoded;
    try{localStorage.setItem(key(owner),JSON.stringify({...d,guestEdited:owner.guest&&dirty}))}catch(e){}
  }
  function apply(d){
    apps=(d.a||[]).map(x=>({...x}));EL=(Array.isArray(d.L)?d.L:(d.a||[])).map(x=>({...x}));FUR=(d.F||[]).map(x=>({...x}));
    RC={...RC0,...(d.C||{})};HT=d.HT||'dorm';NN=d.NN|0||6;FL=d.FL|0;
    WL=Array.isArray(d.WL)?d.WL.map(w=>w.slice()):[];POOL=new Set(d.P||[]);
    DEC=d.DEC??1;PT=d.PT??0;GD=d.GD??1;
    G=d.garden?JSON.parse(JSON.stringify(d.garden)):{m:{},w:5,t:Date.now(),tool:'p:sun'};
    AV={...AVP[0],...(d.avatar||{})};
    PTS=d.shop?.PTS||0;OWN={...(d.shop?.OWN||{})};CLM=d.shop?.CLM||0;
    for(const id of settingIds)if($(id))$(id).value=d.settings?.[id]??defaults[id];
    SEL=null;SELF=null;BM=0;BD=0;DR=null;
    if($('nn'))$('nn').textContent=NN+'×'+NN;
  }
  function loadFor(user){
    if(!user)return;
    if(owner&&key(owner)===key(user))return;
    save();clearTimeout(timer);owner=user;restoring=true;
    let d=null;
    try{d=JSON.parse(localStorage.getItem(key(owner))||'null')}catch(e){}
    dirty=!!d?.guestEdited;
    try{
      apply(d&&typeof d==='object'?d:DEF);
      pl();
      if(!!d?.W!==!!WK.on)wkTog();
      av();shBtn();
    }catch(e){console.warn('home restore',e)}
    finally{restoring=false;const d=snap();last=JSON.stringify({...d,a:d.a.map(({open,...x})=>x),L:d.L.map(({open,...x})=>x),garden:{m:d.garden?.m||{}}});clearTimeout(timer)}
  }
  function after(){
    if(restoring||RT)return;
    clearTimeout(timer);
    timer=setTimeout(()=>{
      save();
      if($('welcomePage')&&!$('welcomePage').hidden)renderWelcomeHousePreview();
    },120);
  }
  {const r0=room;room=function(){const v=r0.apply(this,arguments);after();return v}}
  {const w0=showWelcome;showWelcome=function(user){const u=user||accountUser;if(u)loadFor(u);else if(guestMode)loadFor(GUEST);return w0.apply(this,arguments)}}
  {const e0=enterApp;enterApp=function(user){const u=user||accountUser;if(u)loadFor(u);else if(guestMode)loadFor(GUEST);return e0.apply(this,arguments)}}
  {const o0=openEditableHome;openEditableHome=function(){if(accountUser)loadFor(accountUser);else if(guestMode)loadFor(GUEST);return o0.apply(this,arguments)};window.openEditableHome=openEditableHome}
  window.loadGuestHome=()=>loadFor(GUEST);
  window.saveHomeNow=save;
  window.adoptGuestHome=user=>{
    if(!guestMode||!owner?.guest||!user?.id)return;
    save();
    if(!dirty)return; // An untouched demo must not replace the member's saved home.
    try{
      localStorage.setItem(key(user),JSON.stringify({...snap(),guestEdited:false}));
      localStorage.removeItem(key(GUEST));
      owner=user;dirty=false;
    }catch(e){
      // Keep the current home on screen even if browser storage is unavailable.
      owner=user;
      $('guestStorageNotice').hidden=false;
    }
  };
  window.clearHomeOwner=()=>{
    save();clearTimeout(timer);owner=null;restoring=true;
    try{apply(DEF);pl();if(WK.on)wkTog();av();shBtn()}finally{restoring=false;clearTimeout(timer)}
  };
  window.saveHomeSoon=after;
  document.addEventListener('input',e=>{if(settingIds.includes(e.target.id))after()});
  window.addEventListener('pagehide',save);
  window.addEventListener('beforeunload',save);
  if(accountUser)loadFor(accountUser);

})();

/* ===== Welcome preview shows the walking avatar too (walk / sit / lie, same z-order as the room) ===== */
(function(){
  const ID=/\bid="(wk3|wkw|wk|wkr)"/g;           // rename ids so $('wk') etc. keep pointing at the real room
  renderWelcomeHousePreview=function(){
    const source=$('room'),target=$('welcomeRoomPreview');
    if(!source||!target)return;
    let svg=source.innerHTML||'';
    svg=svg
      .replaceAll('id="stk"','id="preview_stk"').replaceAll('url(#stk)','url(#preview_stk)')
      .replaceAll('id="sh"','id="preview_sh"').replaceAll('url(#sh)','url(#preview_sh)')
      .replaceAll('style="cursor:grab"','');
    // keep the walker's slot: swap the live WebGL canvas for a 2D canvas that is painted every frame
    svg=svg.replace(/<foreignObject id="wk3"([^>]*)>[\s\S]*?<\/foreignObject>/,
      '<foreignObject id="wk3"$1><canvas id="pvWkCv" style="display:block;width:100%;height:100%"></canvas></foreignObject>');
    svg=svg.replace(/<foreignObject[\s\S]*?<\/foreignObject>/g,m=>m.includes('pvWkCv')?m:'');
    svg=svg.replace(ID,'id="pv_$1"');
    const vb=source.getAttribute('viewBox');if(vb)target.setAttribute('viewBox',vb);
    target.innerHTML=svg;
    hookRender();drawMirror();

    const total=EL.reduce((sum,a)=>sum+kw(a),0),price=+$('price').value||0;
    if($('welcomeHomeKwh'))$('welcomeHomeKwh').textContent=total.toFixed(0);
    if($('welcomeHomeCost'))$('welcomeHomeCost').textContent=(total*price).toFixed(0);
    if($('welcomeHomeCurrency'))$('welcomeHomeCurrency').textContent=cur();
  };

  function drawMirror(){
    const cv=document.getElementById('pvWkCv'),W=window.WK3;
    if(!cv||!W||!W.R||!W.R.domElement)return;
    const src=W.R.domElement;
    if(!src.width||!src.height)return;
    if(cv.width!==src.width||cv.height!==src.height){cv.width=src.width;cv.height=src.height}
    const c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);c.drawImage(src,0,0);
  }
  // paint right after each WebGL render (the drawing buffer is only guaranteed valid then)
  function hookRender(){
    const W=window.WK3;
    if(!W||!W.R||W.R.__pvHook)return;
    const r0=W.R.render.bind(W.R);
    W.R.render=function(a,b){const v=r0(a,b);try{drawMirror()}catch(e){}return v};
    W.R.__pvHook=1;
  }

  function sync(){
    requestAnimationFrame(sync);
    const wp=$('welcomePage'),T=$('welcomeRoomPreview');
    if(!wp||wp.hidden||!T||!WK.on)return;
    hookRender();
    const room=$('room');
    // walker slot position / size (3D) or transform (2D fallback), ripples for the pool
    const f=room.querySelector('#wk3'),pf=T.querySelector('#pv_wk3');
    if(f&&pf)for(const k of ['x','y','width','height'])if(pf.getAttribute(k)!==f.getAttribute(k))pf.setAttribute(k,f.getAttribute(k));
    const w=room.querySelector('#wk'),pw=T.querySelector('#pv_wk');
    if(w&&pw){const tr=w.getAttribute('transform');if(pw.getAttribute('transform')!==tr)pw.setAttribute('transform',tr)}
    const r=room.querySelector('#wkr'),pr=T.querySelector('#pv_wkr');
    if(r&&pr){const tr=r.getAttribute('transform');if(pr.getAttribute('transform')!==tr)pr.setAttribute('transform',tr);pr.style.display=r.style.display}
    // painter order: walk in front of / behind furniture exactly like the real room
    const sw=room.querySelector('#wkw'),pv=T.querySelector('#pv_wkw');
    if(sw&&pv&&sw.dataset.z!==pv.dataset.z){
      const i=Array.prototype.indexOf.call(sw.parentNode.children,sw),par=pv.parentNode;
      pv.dataset.z=sw.dataset.z;par.removeChild(pv);par.insertBefore(pv,par.children[i]||null);
    }
    // sit / lie / stand / walk-in-pool changes call room() -> debounced re-render above
  }
  requestAnimationFrame(sync);
})();

/* ===== Tap empty space in the room (floor / wall / grass) -> clear the selection highlight ===== */
(function(){
  let hitItem=false,down=null;
  const ITEM='[data-k],[data-f]';
  const clear=()=>{
    if(SEL==null&&SELF==null)return false;
    SEL=null;SELF=null;
    try{room()}catch(e){console.warn(e)}
    return true;
  };
  RM.addEventListener('pointerdown',e=>{hitItem=!!(e.target.closest&&e.target.closest(ITEM));down=[e.clientX,e.clientY]},true);
  RM.addEventListener('click',e=>{
    if(BM||hitItem)return;                                   // build mode, or the tap started on an item
    if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return; // it was a drag, not a tap
    clear();
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('p0').hidden)clear()});
  // Tap empty space anywhere else on the My Home page (outside the room, items, toolbars, palette) -> clear too
  let start=null;
  const KEEP=ITEM+',#room,button,a,input,select,textarea,label,summary,.selbar,.pal,.pi,.tabs,.tools,#av,#mini,#gdw,.shm';
  document.addEventListener('pointerdown',e=>{start=e.target},true);
  document.addEventListener('click',e=>{
    const p0=$('p0');
    if(!p0||p0.hidden||BM||!e.target.isConnected)return;
    const el=start&&start.closest?start:e.target;
    if(el.closest(KEEP))return;
    clear();
  });
})();

/* ===== Bills are remembered per account (localStorage, this browser). Saved on every edit,
   restored on login, and cleared from the screen on logout so the next person never sees them. ===== */
(function(){
  let owner=null,timer=null;
  const key=u=>'bills1:'+(u&&u.id||'');
  const clean=b=>({m:String(b&&b.m!=null?b.m:''),amt:b&&b.amt!=null&&isFinite(+b.amt)?+b.amt:null,kwh:b&&b.kwh!=null&&isFinite(+b.kwh)?+b.kwh:null});
  function saveNow(){
    clearTimeout(timer);
    if(!owner||!owner.id)return;
    try{localStorage.setItem(key(owner),JSON.stringify({bills:bills.map(clean),cur:$('cur')?$('cur').value:''}))}catch(e){}
  }
  function saveSoon(){clearTimeout(timer);timer=setTimeout(saveNow,250)}
  function loadFor(user){
    if(!user||!user.id)return;
    if(owner&&owner.id===user.id)return;
    owner=user;
    let d=null;
    try{d=JSON.parse(localStorage.getItem(key(owner))||'null')}catch(e){}
    bills=d&&Array.isArray(d.bills)?d.bills.map(clean):[];
    if(d&&d.cur&&$('cur'))try{$('cur').value=d.cur}catch(e){}
    D={};
    try{rows()}catch(e){console.warn('bills restore',e)}
  }
  window.saveBillsNow=saveNow;
  // Save genuine bill edits; guest sample rows have no account owner.
  {const r0=rows;rows=function(){const v=r0.apply(this,arguments);saveSoon();return v}}
  if($('rows'))$('rows').addEventListener('input',saveSoon);
  if($('cur'))$('cur').addEventListener('change',saveSoon);
  {const e0=enterApp;enterApp=function(user){const u=user||accountUser;if(u)loadFor(u);return e0.apply(this,arguments)}}
  {const w0=showWelcome;showWelcome=function(user){const u=user||accountUser;if(u)loadFor(u);return w0.apply(this,arguments)}}
  {const o0=performLogout;performLogout=async function(){
    saveNow();                                   // keep this account's bills before leaving
    const v=await o0.apply(this,arguments);
    if(!accountUser){owner=null;bills=[];D={};try{rows()}catch(e){}}   // empty the screen for the next login
    return v;
  }}
  // re-bind logout buttons to the wrapped function
  if($('logoutButton'))$('logoutButton').onclick=()=>performLogout($('logoutButton'));
  if($('welcomeLogoutButton'))$('welcomeLogoutButton').onclick=()=>performLogout($('welcomeLogoutButton'));
  window.addEventListener('pagehide',saveNow);
  window.addEventListener('beforeunload',saveNow);
  if(accountUser)loadFor(accountUser);          // already signed in when the page opened
})();


/* Keep a typed message across guest login, reloads and account changes.
   A guest may type a draft; only an authenticated member can send to Gemini. */
(function(){
  let owner=null;
  const key=u=>'chatDraft1:'+(u?.guest?'guest':u?.id||'guest');
  function saveNow(){
    if(!owner||!$('q'))return;
    try{localStorage.setItem(key(owner),JSON.stringify({text:$('q').value}))}catch(e){}
  }
  function loadFor(user){
    if(!user)return;
    if(owner&&key(owner)===key(user))return;
    saveNow();owner=user;
    let d=null;
    try{d=JSON.parse(localStorage.getItem(key(owner))||'null')}catch(e){}
    $('q').value=typeof d?.text==='string'?d.text:'';
  }
  window.loadGuestDraft=()=>loadFor({guest:true});
  window.adoptGuestDraft=user=>{
    if(!guestMode||!owner?.guest||!user?.id)return;
    saveNow();
    if(!$('q').value)return;
    owner=user;saveNow();
    try{localStorage.removeItem('chatDraft1:guest')}catch(e){}
  };
  window.clearChatDraftOwner=()=>{owner=null;$('q').value=''};
  $('q').addEventListener('input',saveNow);
  {const w0=showWelcome;showWelcome=function(user){const u=user||accountUser;if(u)loadFor(u);return w0.apply(this,arguments)}}
  {const e0=enterApp;enterApp=function(user){const u=user||accountUser;if(u)loadFor(u);return e0.apply(this,arguments)}}
  {const a0=ask;ask=function(){const result=a0.apply(this,arguments);saveNow();return result}}
  {const o0=performLogout;performLogout=async function(){saveNow();return o0.apply(this,arguments)}}
  if($('logoutButton'))$('logoutButton').onclick=()=>performLogout($('logoutButton'));
  if($('welcomeLogoutButton'))$('welcomeLogoutButton').onclick=()=>performLogout($('welcomeLogoutButton'));
  window.addEventListener('pagehide',saveNow);
  window.addEventListener('beforeunload',saveNow);
  if(accountUser)loadFor(accountUser);
})();

/* =========================================================
   SIDEBAR — collapse immediately after selecting a page.
   Behaviour-only patch. No other app logic is changed.
========================================================= */
(function(){
  const side=document.querySelector('.side');
  if(!side)return;

  const isDesktop=()=>window.matchMedia('(min-width:861px)').matches;
  const collapseAfterClick=()=>{
    if(!isDesktop())return;
    const active=document.activeElement;
    if(active&&typeof active.blur==='function')active.blur();
    side.classList.add('nav-auto-collapse');
  };

  side.querySelectorAll('.side-nav button,.side-home-card,#settingsButton').forEach(el=>{
    el.addEventListener('click',()=>requestAnimationFrame(collapseAfterClick));
  });

  side.addEventListener('pointerleave',()=>{
    side.classList.remove('nav-auto-collapse');
  });

  window.addEventListener('resize',()=>{
    if(!isDesktop())side.classList.remove('nav-auto-collapse');
  });
})();
